package com.jaydeep.jobhunter;
import java.util.*;
public class JobHunterApp {public static void main(String[] args)throws Exception{List<JobCollector> cs=List.of(new GreenhouseCollector(List.of("airbnb","stripe","datadog","cloudflare","hubspot","plaid","reddit","ramp","coinbase","duolingo","figma","notion","okta","asana","brex","rippling","toast","affirm","lyft","doordash")),new LeverCollector(List.of("netflix","shopify","scaleai","anduril","anthropic","intercom","samsara","mistral","pinterest","coursera","udemy","benchling","faire","gusto","flexport")),new AshbyCollector(List.of("Ashby","OpenAI","Ramp","Linear","Notion","Vercel","Figma","Rippling")),new RemoteOkCollector());List<Job> all=new ArrayList<>();for(JobCollector c:cs)try{List<Job> x=c.collect();System.out.println(c.name()+": "+x.size());all.addAll(x);}catch(Exception e){System.err.println("["+c.name()+"] "+e.getMessage());}Map<String,Job> unique=new LinkedHashMap<>();for(Job j:all)if(j.url()!=null&&!j.url().isBlank()&&JobMatcher.relevant(j))unique.putIfAbsent(norm(j.url()),j);SeenStore seen=new SeenStore("seen_urls.txt");List<Job> fresh=unique.values().stream().filter(j->!seen.contains(j.url())).sorted(Comparator.comparingInt(JobMatcher::score).reversed()).limit(40).toList();System.out.println("Relevant="+unique.size()+", fresh="+fresh.size());if(fresh.isEmpty())return;new EmailSender().send(fresh);seen.mark(fresh.stream().map(Job::url).toList());System.out.println("Email sent; dedup state updated.");}private static String norm(String u){return u.trim().replaceAll("[?#].*$","");}}
